<?php
/** Proof — the secure link and the customer's claim (spec "Proof", 3). */
require __DIR__ . '/lib.php';
$bea = as_member(27);
$fx = ar_fixture();
$cust = mk_customer('SMOKE Link Customer', ['billing_address' => '9 Link Lane']);
$inv = mk_invoice($cust, [['Consulting', '2', '500.00'], ['Parts', '1', '100.00', (string) $fx['tax'], '4000']], ['issue_date' => '2026-05-10', 'reference' => 'PO-LINK']);
$r = issue($inv);
$number = (string) $r['number'];
act($bea, '/notes/save.php', ['record_type' => 'invoice', 'record_id' => $inv, 'body' => 'SMOKE internal note: do not show']);
$tok = held_token($inv);
echo "1. The page\n";
$jar = jar();
$r = req('GET', '/i/' . $tok, ['jar' => $jar]);
$b = $r['body'];
ok($r['code'] === 200 && str_contains($b, $number) && str_contains($b, 'Consulting') && str_contains($b, 'Parts') && str_contains($b, 'id="print-balance"') && str_contains($b, '1,108.25 USD'), 'the page shows the number, the lines and the balance due (1,108.25 USD)');
ok(str_contains($b, '9 Link Lane') && str_contains($b, 'id="print-business">SMOKE Co<'), 'the business\'s name and the customer\'s billing address');
ok(one("SELECT email::text FROM customers WHERE id = :c", ['c' => $cust]) === 'smokelinkcustomer@example.invalid' && !str_contains($b, 'smokelinkcustomer@example.invalid') && !str_contains($b, 'SMOKE internal note') && !str_contains($b, 'nxl-navigation') && str_contains($r['headers'], 'X-Robots-Tag: noindex') && str_contains($r['headers'], 'no-store'), 'never the customer\'s email or an internal note; no shell; noindex and no-store');
ok(!preg_match('/INV-\d{5}/', preg_replace('/' . preg_quote($number, '/') . '/', '', $b)), 'and no other invoice\'s number');
ok(str_contains($b, 'id="claim-form"') && str_contains($b, 'name="website"') && str_contains($b, 'id="public-print-btn"'), 'the claim form (with its honeypot) and the Print button');
$p = req('GET', '/i/' . $tok . '/print');
ok($p['code'] === 200 && str_contains($p['body'], 'id="print-lines"') && !str_contains($p['body'], 'id="claim-form"') && !str_contains($p['body'], 'id="public-print-btn"'), 'the print layout: the invoice, no claim form, no button');
$log = q("SELECT source, actor_member_id, actor_customer_id, after FROM activity_log WHERE action = 'invoice.view' AND journal_entry_id IS NULL ORDER BY id DESC LIMIT 2");
ok(count($log) === 2 && $log[0]['source'] === 'portal' && $log[0]['actor_member_id'] === null && (int) $log[0]['actor_customer_id'] === $cust && !str_contains((string) $log[0]['after'], $tok), 'invoice.view is logged: source portal, actor_customer_id, no member, never the token');
echo "2. Dead links\n";
$d1 = req('GET', '/i/' . str_repeat('0', 48));
ok($d1['code'] === 404 && str_contains($d1['body'], 'id="dead-link-title">This link has expired.<') && str_contains($d1['body'], 'Ask the business for a new one.'), 'an unknown token: the one dead-link page, 404');
ok(req('GET', '/i/' . str_repeat('0', 48) . '/print')['code'] === 404, 'its print page too');
echo "3. The claim\n";
$csrf = preg_match('/name="csrf_token" value="([^"]+)"/', $b, $m) ? $m[1] : '';
ok($csrf !== '', 'the form carries a CSRF token from the anonymous session');
$post = fn (array $f, ?string $j = null, ?string $t = null) => req('POST', '/i/' . ($t ?? $tok) . '/claim', ['jar' => $j ?? $jar, 'form' => $f]);
$r = req('POST', '/i/' . $tok . '/claim', ['jar' => jar(), 'form' => ['claimed_on' => '2026-05-20', 'method' => 'transfer']]);
ok($r['code'] === 403, 'a claim without the session\'s CSRF token: 403');
$since = last_activity_id();
$r = $post(['csrf_token' => $csrf, 'claimed_on' => '2026-05-20', 'method' => 'transfer', 'reference' => 'LINK-9', 'amount' => '500', 'note' => 'SMOKE paid half']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="claim-done-title">Thank you.<'), 'a claim: the thank-you page');
$k = q('SELECT * FROM receipt_claims WHERE invoice_id = :i ORDER BY id DESC LIMIT 1', ['i' => $inv])[0];
ok($k['status'] === 'submitted' && $k['amount'] === '500.00' && $k['method'] === 'transfer' && $k['reference'] === 'LINK-9' && $k['ip_address'] !== null, 'a receipt_claims row with the amount, the method and the address (' . $k['ip_address'] . ')');
$l = activity('claim.submit', $since)[0] ?? null;
ok($l !== null && $l['source'] === 'portal' && (int) $l['actor_customer_id'] === $cust && $l['actor_member_id'] === null && (int) $l['customer_id'] === $cust && !str_contains((string) $l['after'], $tok) && str_contains((string) $l['after'], '"amount": "500.00"'), 'claim.submit: source portal, actor_customer_id, the amount and the method, no token');
ok((string) one('SELECT balance_due FROM invoices WHERE id = :i', ['i' => $inv]) === '1108.25' && (int) one('SELECT count(*) FROM receipts WHERE customer_id = :c', ['c' => $cust]) === 0, 'a claim moves no money: the balance is unchanged and no receipt exists');
$n = q("SELECT title, record_type, record_id FROM notifications WHERE member_id = 27 AND kind = 'claim_submitted' ORDER BY id DESC LIMIT 1")[0] ?? null;
ok($n !== null && str_contains($n['title'], 'SMOKE Link Customer says they paid ' . $number) && $n['record_type'] === 'invoice' && (int) $n['record_id'] === $inv, 'the Bookkeeper has an in-app notice');
$body = page($bea, '/invoices/' . $inv)['body'];
ok(str_contains($body, 'id="invoice-claims"') && str_contains($body, 'id="invoice-head-claim"') && str_contains($body, '/receipts/new?claim=' . $k['id']), 'the invoice page shows the claim with Confirm');
$before = (int) one('SELECT count(*) FROM receipt_claims WHERE invoice_id = :i', ['i' => $inv]);
$r = $post(['csrf_token' => $csrf, 'claimed_on' => '2026-05-21', 'method' => 'cash', 'website' => 'http://spam.invalid']);
ok($r['code'] === 200 && str_contains($r['body'], 'Thank you') && (int) one('SELECT count(*) FROM receipt_claims WHERE invoice_id = :i', ['i' => $inv]) === $before, 'a filled honeypot is told thanks and nothing is stored');
$r = $post(['csrf_token' => $csrf, 'claimed_on' => '2099-01-01', 'method' => 'cash']);
ok($r['code'] === 422 && str_contains($r['body'], 'cannot be in the future'), 'a date in the future: 422 on a plain page');
$r = $post(['csrf_token' => $csrf, 'claimed_on' => '2026-05-21', 'method' => 'barter']);
ok($r['code'] === 422 && str_contains($r['body'], 'Say how you paid'), 'an unknown method: 422');
$r = $post(['csrf_token' => $csrf, 'claimed_on' => '2026-05-21', 'method' => 'cash', 'amount' => 'lots']);
ok($r['code'] === 422, 'a bad amount: 422');
echo "4. The rate limit\n";
$codes = [];
foreach ([2, 3, 4] as $i) { $codes[] = $post(['csrf_token' => $csrf, 'claimed_on' => '2026-05-2' . $i, 'method' => 'cash', 'amount' => '1'])['code']; }
ok($codes === [200, 200, 429], 'three claims an hour per invoice: the second and third are taken, the fourth refused (429): ' . implode(', ', $codes));
ok((int) one('SELECT count(*) FROM receipt_claims WHERE invoice_id = :i', ['i' => $inv]) === 3, 'three claims stored');
$r = req('POST', '/i/' . str_repeat('1', 48) . '/claim', ['jar' => $jar, 'form' => ['csrf_token' => $csrf, 'claimed_on' => '2026-05-20', 'method' => 'cash']]);
ok($r['code'] === 404, 'a claim on a dead token: 404');
echo "5. After a rotate\n";
act($bea, '/invoices/secure-link.php', ['invoice' => $inv]);
$r = $post(['csrf_token' => $csrf, 'claimed_on' => '2026-05-20', 'method' => 'cash']);
ok($r['code'] === 404 && req('GET', '/i/' . $tok)['code'] === 404, 'the rotated token neither shows nor takes a claim');
$new = held_token($inv);
$r = req('GET', '/i/' . $new);
ok($r['code'] === 200, 'the new one opens');
q("INSERT INTO receipts (customer_id, received_on, amount, currency, method, recorded_by) VALUES (:c, '2026-05-25', 300, 'USD', 'cash', 27)", ['c' => $cust]);
$rid = (int) one('SELECT max(id) FROM receipts WHERE customer_id = :c', ['c' => $cust]);
one('SELECT gl_receipt_post(:r, 27)', ['r' => $rid]);
q('INSERT INTO receipt_applications (receipt_id, invoice_id, amount, applied_by) VALUES (:r, :i, 300, 27)', ['r' => $rid, 'i' => $inv]);
$r = req('GET', '/i/' . $new);
ok(str_contains($r['body'], 'id="public-received"') && str_contains($r['body'], '300.00 USD') && str_contains($r['body'], '808.25 USD'), 'what was received shows, and the balance falls (808.25 USD)');
finish();
